import { readFileSync, rmSync } from "node:fs";
import { resolve } from "node:path";
import { z } from "zod";
import { writeFileBestEffort } from "./bestEffortFs.js";
/** Fixed path a pre-run-dir script self-writes; kept only as a read fallback. */
export const LEGACY_RESULT_PATH = "scripts/replay-result.json";
/**
 * Minimal shape a captured value must have to count as a ReplayResult: an items
 * array and a test-run id (camelCase or the snake_case SDK alias). This gates
 * "did we actually capture a result?" so an arbitrary stdout JSON blob (a
 * dependency's log line, a config dump) is never mistaken for the run's result.
 */
const replayResultSchema = z
    .object({
    items: z.array(z.unknown()),
    testRunId: z.string().optional(),
    test_run_id: z.string().optional(),
    testRunUrl: z.string().optional(),
    test_run_url: z.string().optional(),
})
    .passthrough()
    .refine(({ testRunId, test_run_id }) => testRunId !== undefined || test_run_id !== undefined);
/**
 * Validate that an already-parsed value is a ReplayResult. Returns the parsed
 * value on success so callers treat a shape mismatch as "no result captured"
 * (unverified) rather than crashing or persisting a bogus result.
 */
export function validateReplayResult(result) {
    const parsed = replayResultSchema.safeParse(result);
    return parsed.success ? { ok: true, result: parsed.data } : { ok: false };
}
export function clearPreviousResult(out) {
    if (!out) {
        return;
    }
    try {
        rmSync(resolve(out), { force: true });
    }
    catch {
        // Best-effort: a stale result should not block the replay command itself.
    }
}
/**
 * Resolve the run's ReplayResult in order of trust: the run-dir result file,
 * then this run's stdout JSON, then the legacy fixed path. stdout is noisy (env
 * loaders, frameworks), so it's compatibility-only and never beats the file.
 * Whatever resolves is mirrored to `out` so `run.json` never points at nothing.
 */
export function parseReplayResult(out, body) {
    const fileResult = readExistingResult(out);
    if (fileResult.ok) {
        return fileResult;
    }
    if (body.trim().length > 0) {
        const stdoutResult = parseReplayResultOutput(body);
        if (stdoutResult.ok) {
            writeCompatibilityResult(out, JSON.stringify(stdoutResult.result));
            return stdoutResult;
        }
        // Not ReplayResult JSON: a legacy script may print a human summary here and
        // write the result to the legacy file instead. Fall through.
    }
    const legacyResult = readExistingResult(resolve(LEGACY_RESULT_PATH));
    if (legacyResult.ok) {
        writeCompatibilityResult(out, JSON.stringify(legacyResult.result));
        return legacyResult;
    }
    if (body.trim().length > 0) {
        process.stderr.write(`replayProgress: captured stdout does not contain ReplayResult JSON${out ? `; left ${out} as the replay script wrote it` : ""}. ` +
            "The SDK writes BITFAB_REPLAY_RESULT_PATH automatically when available; legacy scripts should print clean ReplayResult JSON to stdout and human output to stderr.\n");
    }
    return { ok: false };
}
/**
 * Parse clean ReplayResult JSON or recover it after a package-runner banner.
 * Only `{` at column zero can start a fallback candidate, so nested values in
 * pretty-printed JSON are ignored.
 */
function parseReplayResultOutput(body) {
    const direct = parseReplayResultJson(body);
    if (direct.ok) {
        return direct;
    }
    const starts = Array.from(body.matchAll(/^\{/gm), (match) => match.index);
    for (let i = starts.length - 1; i >= 0; i--) {
        const candidate = parseReplayResultJson(body.slice(starts[i]));
        if (candidate.ok) {
            return candidate;
        }
    }
    return { ok: false };
}
function parseReplayResultJson(json) {
    try {
        return validateReplayResult(JSON.parse(json));
    }
    catch {
        return { ok: false };
    }
}
export function writeCompatibilityResult(out, body) {
    if (!out) {
        return;
    }
    // Best-effort: the event log still carries the parsed result.
    writeFileBestEffort(resolve(out), body);
}
function readExistingResult(out) {
    if (!out) {
        return { ok: false };
    }
    try {
        return parseReplayResultJson(readFileSync(out, "utf8"));
    }
    catch {
        return { ok: false };
    }
}
